-- Ejecutar en Supabase > SQL Editor. Requiere Auth por correo habilitado.
create extension if not exists pgcrypto;
create table if not exists public.workspaces(id uuid primary key default gen_random_uuid(),name text not null,created_by uuid not null references auth.users(id),created_at timestamptz default now());
create table if not exists public.memberships(workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in ('owner','member')),primary key(workspace_id,user_id));
create table if not exists public.invites(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,code text unique not null default encode(gen_random_bytes(20),'hex'),created_by uuid not null references auth.users(id),expires_at timestamptz not null default now()+interval '7 days',used_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.templates(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,employees jsonb not null default '[]'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.repartos(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,period text not null,days integer not null check(days between 1 and 31),total numeric(14,2) not null check(total>=0),snapshot jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz default now());
create index if not exists memberships_user_idx on public.memberships(user_id);
create index if not exists templates_workspace_idx on public.templates(workspace_id);
create index if not exists repartos_workspace_idx on public.repartos(workspace_id,created_at desc);
create or replace function public.is_member(w uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.workspace_id=w and m.user_id=(select auth.uid()))$$;
create or replace function public.is_owner(w uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.workspace_id=w and m.user_id=(select auth.uid()) and m.role='owner')$$;
create or replace function public.create_workspace(p_name text) returns uuid language plpgsql security definer set search_path='' as $$declare w uuid;begin if auth.uid() is null then raise exception 'Inicia sesión';end if;if length(trim(p_name))<2 then raise exception 'Nombre inválido';end if;insert into public.workspaces(name,created_by) values(trim(p_name),auth.uid()) returning id into w;insert into public.memberships(workspace_id,user_id,role) values(w,auth.uid(),'owner');return w;end$$;
create or replace function public.create_invite(p_workspace uuid) returns text language plpgsql security definer set search_path='' as $$declare c text;begin if not public.is_owner(p_workspace) then raise exception 'Solo el propietario puede invitar';end if;insert into public.invites(workspace_id,created_by) values(p_workspace,auth.uid()) returning code into c;return c;end$$;
create or replace function public.redeem_invite(p_code text) returns uuid language plpgsql security definer set search_path='' as $$declare w uuid;begin if auth.uid() is null then raise exception 'Inicia sesión';end if;update public.invites set used_by=auth.uid() where code=trim(p_code) and used_by is null and expires_at>now() returning workspace_id into w;if w is null then raise exception 'Código inválido, usado o vencido';end if;insert into public.memberships(workspace_id,user_id,role) values(w,auth.uid(),'member') on conflict do nothing;return w;end$$;
revoke all on function public.is_member(uuid),public.is_owner(uuid),public.create_workspace(text),public.create_invite(uuid),public.redeem_invite(text) from public;
grant execute on function public.is_member(uuid),public.is_owner(uuid),public.create_workspace(text),public.create_invite(uuid),public.redeem_invite(text) to authenticated;
alter table public.workspaces enable row level security;alter table public.memberships enable row level security;alter table public.invites enable row level security;alter table public.templates enable row level security;alter table public.repartos enable row level security;
create policy "workspace read" on public.workspaces for select to authenticated using(public.is_member(id));
create policy "members read" on public.memberships for select to authenticated using(public.is_member(workspace_id));
create policy "templates read" on public.templates for select to authenticated using(public.is_member(workspace_id));
create policy "templates insert" on public.templates for insert to authenticated with check(public.is_member(workspace_id));
create policy "templates update" on public.templates for update to authenticated using(public.is_member(workspace_id)) with check(public.is_member(workspace_id));
create policy "templates delete" on public.templates for delete to authenticated using(public.is_member(workspace_id));
create policy "repartos read" on public.repartos for select to authenticated using(public.is_member(workspace_id));
create policy "repartos insert" on public.repartos for insert to authenticated with check(public.is_member(workspace_id) and created_by=(select auth.uid()));
-- Historial inmutable: no policies UPDATE/DELETE.
